class _Node:
    __slots__ = ("children", "weight")

    def __init__(self):
        self.children = {}
        self.weight = 0


class AutoComplete:
    def __init__(self):
        self._root = _Node()
        self._count = 0

    @staticmethod
    def _clean(word):
        if not isinstance(word, str) or not word.strip():
            raise ValueError("Word required")
        return word.strip().lower()

    def _find(self, text):
        node = self._root
        for char in text:
            node = node.children.get(char)
            if node is None:
                return None
        return node

    def add(self, word, weight=1):
        word = self._clean(word)
        if type(weight) is not int or weight < 1:
            raise ValueError("Weight must be positive")
        node = self._root
        for char in word:
            node = node.children.setdefault(char, _Node())
        if node.weight == 0:
            self._count += 1
        node.weight += weight

    def _known(self, word):
        node = self._find(self._clean(word))
        if node is None or node.weight == 0:
            raise ValueError("Unknown word")
        return node

    def record(self, word):
        self._known(word).weight += 1

    def remove(self, word):
        node = self._known(word)
        node.weight = 0
        self._count -= 1

    def weight(self, word):
        node = self._find(self._clean(word))
        return node.weight if node else 0

    def suggest(self, prefix, limit=3):
        if type(limit) is not int or limit < 1:
            raise ValueError("Limit must be positive")
        prefix = prefix.lower()
        start = self._find(prefix)
        if start is None:
            return []
        found = []
        stack = [(start, prefix)]
        while stack:
            node, text = stack.pop()
            if node.weight:
                found.append((-node.weight, text))
            for char, child in node.children.items():
                stack.append((child, text + char))
        found.sort()
        return [text for _, text in found[:limit]]

    def __len__(self):
        return self._count
